    @Test
    void tourismTaxChargesPerGuestPerNightOnThePaidReservationsStartingInTheMonth() {
        Guest guest = new Guest("Bruno Lima", "bruno@example.com", "987.654.321-00");
        Reservation two = service.create(new NewReservation(
                202, guest, LocalDate.parse("2027-04-10"), LocalDate.parse("2027-04-13"), 2, RatePlan.STANDARD));
        service.confirm(two.id());

        String csv = new TourismTaxReport(store, new BigDecimal("4.50")).generate(YearMonth.of(2027, 4));

        assertEquals("""
                Pousada Maré Alta,tourism-tax,2027-04
                reservation,room,check_in,check_out,guests,nights,tax
                1,201,2027-04-01,2027-04-03,1,2,9.00
                3,301,2027-04-02,2027-04-04,1,2,9.00
                6,202,2027-04-10,2027-04-13,2,3,27.00
                total,45.00
                """, csv);
    }

    @Test
    void ratePlansHaveALineEachEvenWithoutReservations() {
        String april = new RatePlanReport(store).generate(YearMonth.of(2027, 4));
        String march = new RatePlanReport(store).generate(YearMonth.of(2027, 3));
        String june = new RatePlanReport(store).generate(YearMonth.of(2027, 6));

        assertEquals("""
                Pousada Maré Alta,rate-plans,2027-04
                rate_plan,reservations,amount
                STANDARD,2,1939.60
                NON_REFUNDABLE,0,0.00
                total,2,1939.60
                """, april);
        assertEquals("""
                Pousada Maré Alta,rate-plans,2027-03
                rate_plan,reservations,amount
                STANDARD,0,0.00
                NON_REFUNDABLE,1,%s
                total,1,%s
                """.formatted(amountOfLateMarch(), amountOfLateMarch()), march);
        assertEquals("""
                Pousada Maré Alta,rate-plans,2027-06
                rate_plan,reservations,amount
                STANDARD,0,0.00
                NON_REFUNDABLE,0,0.00
                total,0,0.00
                """, june);
    }

    private String amountOfLateMarch() {
        return store.find(2).orElseThrow().amountKept().toPlainString();
    }
}
